function r({registerIndicator:c,nulls:l}){c({id:"oa-oc2",name:"Open-Close Midpoint (OC2)",category:"Numerics",placement:"onchart",inputs:[],plots:[{key:"oc2",type:"line",title:"OC2",style:{color:"#ffeb3b",lineWidth:2}}],calc(t){const o=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++){const n=t[e].open,i=t[e].close;!Number.isFinite(n)||!Number.isFinite(i)||(o[e]=(n+i)*.5)}return{oc2:l(o)}}})}export{r as default};
